-- WoW Forever quests our world lacked whose givers, enders, kill targets and items are all in our world now (with
-- 2026_11_21_90): Everlake's batches C to G and its object quests, plus Icy Veins' turn-in and progress words.
-- Data from Everlake (GPL-3.0), commit cf07dad, files 2026_11_19_984, 986, 989, 991, 994 and 996 (quests: EG Link's record of
-- the live client's quest records, Efficient Games, https://efficient.games, CC BY 4.0, folder 70959; givers and enders from
-- QuestieDB, Questie team, GPL-3.0, and Wowhead's and Icy Veins' WoW Forever databases) and its Forge imports 196, 200, 206 and
-- 210 (texts from Icy Veins' WoW Forever database, db.icy-veins.com/wow-forever). Changed: only quests our world can run, checked
-- against our world and written as our own rows. The rest wait for NPCs or items no allowed source gives yet.
-- Everything goes in only where missing. Safe to run more than once.


DROP TEMPORARY TABLE IF EXISTS `forever_q21_quest_template`;
CREATE TEMPORARY TABLE `forever_q21_quest_template` SELECT `ID`,`RewardItem1`,`RewardAmount1`,`ItemDrop1`,`ItemDropQuantity1`,`RewardItem2`,`RewardAmount2`,`ItemDrop2`,`ItemDropQuantity2`,`RewardItem3`,`RewardAmount3`,`ItemDrop3`,`ItemDropQuantity3`,`RewardItem4`,`RewardAmount4`,`ItemDrop4`,`ItemDropQuantity4`,`RewardChoiceItemID1`,`RewardChoiceItemQuantity1`,`RewardChoiceItemID2`,`RewardChoiceItemQuantity2`,`RewardChoiceItemID3`,`RewardChoiceItemQuantity3`,`RewardChoiceItemID4`,`RewardChoiceItemQuantity4`,`RewardChoiceItemID5`,`RewardChoiceItemQuantity5`,`RewardChoiceItemID6`,`RewardChoiceItemQuantity6`,`RewardFactionID1`,`RewardFactionValue1`,`RewardFactionOverride1`,`RewardFactionCapIn1`,`RewardFactionID2`,`RewardFactionValue2`,`RewardFactionOverride2`,`RewardFactionCapIn2`,`RewardFactionID3`,`RewardFactionValue3`,`RewardFactionOverride3`,`RewardFactionCapIn3`,`RewardFactionID4`,`RewardFactionValue4`,`RewardFactionOverride4`,`RewardFactionCapIn4`,`RewardFactionID5`,`RewardFactionValue5`,`RewardFactionOverride5`,`RewardFactionCapIn5`,`RewardCurrencyID1`,`RewardCurrencyQty1`,`RewardCurrencyID2`,`RewardCurrencyQty2`,`RewardCurrencyID3`,`RewardCurrencyQty3`,`RewardCurrencyID4`,`RewardCurrencyQty4`,`QuestType`,`QuestInfoID`,`RewardNextQuest`,`StartItem`,`Flags`,`FlagsEx`,`FlagsEx2`,`TimeAllowed`,`QuestSortID`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardSpell`,`AllowableRaces`,`AcceptedSoundKitID`,`CompleteSoundKitID`,`Expansion`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog` FROM `quest_template` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_q21_quest_template`;

