DROP TEMPORARY TABLE IF EXISTS `forever_q21_quest_request_items`;
CREATE TEMPORARY TABLE `forever_q21_quest_request_items` SELECT `ID`,`CompletionText` FROM `quest_request_items` WHERE 0;
