-- The writs of the Craftsman's Writ quests above join their tier's world drop (2026_11_19_99), as Everlake 990 and 992 do.
SELECT `s`.`Entry`,0,`s`.`Item`,0,0,1,1,1,1,CONCAT('Craftsman''s Writ (quest ',`s`.`Quest`,')') FROM (
  SELECT 9500002 AS `Entry`,264063 AS `Item`,94263 AS `Quest`
  UNION ALL SELECT 9500002,264087,94287
  UNION ALL SELECT 9500003,264124,94324
  UNION ALL SELECT 9500002,264091,94291
  UNION ALL SELECT 9500003,264126,94326
  UNION ALL SELECT 9500003,264127,94327
  UNION ALL SELECT 9500003,264129,94329
  UNION ALL SELECT 9500003,264133,94333
  UNION ALL SELECT 9500003,264148,94348
  UNION ALL SELECT 9500003,264156,94356
  UNION ALL SELECT 9500003,264160,94360) `s`
WHERE EXISTS (SELECT 1 FROM `quest_template` `q` WHERE `q`.`ID`=`s`.`Quest`)
  AND EXISTS (SELECT 1 FROM `reference_loot_template` `r` WHERE `r`.`Entry`=`s`.`Entry`)
  AND NOT EXISTS (SELECT 1 FROM `reference_loot_template` `t` WHERE `t`.`Entry`=`s`.`Entry` AND `t`.`ItemType`=0 AND `t`.`Item`=`s`.`Item`);

-- Quest givers and enders show their marker; "talk to" targets open a window (gossip), so their objective counts.
UPDATE `creature_template` SET `npcflag`=`npcflag`|2 WHERE `entry` IN (332,376,1460,3000,3362,3539,3600,3685,3690,3945,4604,4631,4730,4731,4752,4753,4773,4791,4885,7363,7623,7877,7952,7953,8379,11140,11185,11406,11555,14348,15350,15351,34365,40833,205153,221269,235906,236573,236770,237007,239831,240482,244425,244511,244517,246378,247473,249968,253097,253136,253177,253527,253851,254040,254578,254674,255009,255678,255683,255829,255897,256222,256418,256710,256978,257250,257558,257673,258023,258031,258048,258570,258785,259158,259352,259353,260146,260231,260271,260383,260390,260391,260873,260931,260993,261208,261992,262031,262041,262044,262294,263316,263757,266524,266593,266847,267121,267525,268992,269152,269577,269647) AND (`npcflag`&2)=0;
UPDATE `creature_template` SET `npcflag`=1 WHERE `entry` IN (255685,255771,255773,257250,266593,268313,268314,268316,268318,269138,269139,269140,269141,270542,270543,270544) AND `npcflag`=0;

-- Turn-in and progress words from Icy Veins' WoW Forever database (db.icy-veins.com/wow-forever), as Everlake's Forge
-- imports 196, 200, 206 and 210 give them: only for quests our world has (or gets above) and has no text for.
DROP TEMPORARY TABLE IF EXISTS `forever_tx_offer_reward`;
CREATE TEMPORARY TABLE `forever_tx_offer_reward` SELECT `ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild` FROM `quest_offer_reward` WHERE 0;
  AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward` `x` WHERE `x`.`ID`=`s`.`ID`);
DROP TEMPORARY TABLE IF EXISTS `forever_tx_offer_reward`;

DROP TEMPORARY TABLE IF EXISTS `forever_tx_request_items`;
CREATE TEMPORARY TABLE `forever_tx_request_items` SELECT `ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild` FROM `quest_request_items` WHERE 0;
  AND NOT EXISTS (SELECT 1 FROM `quest_request_items` `x` WHERE `x`.`ID`=`s`.`ID`);
DROP TEMPORARY TABLE IF EXISTS `forever_tx_request_items`;
