INSERT INTO `forever_q21_quest_request_items` (`ID`,`CompletionText`) VALUES
(95418,'So, the Twilight''s Hammer found something in the earth? You were right to banish this evil, $N. If it interests those fanatics, it''s not to be trusted.'),
(96103,'You bring something from the plains?');
